/**
 * The knowledge writer over the generated training repository (decision 0029;
 * madarch-m38l.2). The repository is generated by examples/training-repository,
 * filled into a test store by the extract driver, and the writer's units run
 * with a scripted fake agent: no model. The fake answers as the answer key
 * says the product reads (its service, flow and doc items), reaching the graph
 * only through the writer's tools; the assertions judge what the core accepted
 * and wrote, never what the fake meant.
 *
 * Expected values come from the answer key and from the formats: the domains
 * the graph supports naming (payments and ordering), the statements and the
 * evidence behind them (the key's locations), the refusals (the format).
 *
 * The fill of the training repository takes minutes; the suite fills once.
 * MADARCH_WRITER_FIXTURE names a folder to keep the generated repository and
 * its filled store between runs while developing; CI fills fresh each time.
 */
import { execFileSync } from 'node:child_process';
import { existsSync, mkdirSync, mkdtempSync, readFileSync, rmSync, symlinkSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { afterAll, beforeAll, describe, expect, test } from 'bun:test';
import { parse as parseYaml, parseDocument } from 'yaml';
import { createPGliteDatabaseOwner, type DatabaseOwner } from '../src/adapters/database-owner.js';
import { documentSections } from '../src/knowledge/index/sections.js';
import { localizedSourcePath } from '../src/writer/localized-source.js';
import { statementsOfMarkdown } from '../src/writer/editorial-read.js';
import { fillGraph } from '../src/extract/driver/index.js';
import { KINDS_FILE } from '../src/knowledge/kinds.js';
import { seedStarterSet } from '../src/knowledge/seed.js';
import { HISTORY_EXTRACTOR, OWNERS, TREE_EXTRACTORS } from '../src/extract/driver/extractors.js';
import { createGraphStore, type GraphStore } from '../src/graph/index.js';
import { changedGrounds, gitReader, indexKnowledge, readIndexedPage, statementsRelyingOn } from '../src/knowledge/index/index.js';
import {
  DEFAULT_UNIT_BOUNDS, GraphView, UnitTools, WRITER_TOOLS, fsSink, memoryJournal, memorySink, runWriter, slugOf,
  type DomainDeclaration, type EditorialJudge, type Journal, type MentionName, type ToolAnswer, type UnitAgent, type UnitOutcome, type UnitRequest, type UnitSpec, type WriterReport,
} from '../src/writer/index.js';

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const GENERATOR = path.join(ROOT, 'examples/training-repository/generate.mjs');

interface KeyItem {
  id: string;
  expectedWikiStatement: string;
  evidenceClass: string;
  location?: { path: string; symbol?: string; anchor?: string };
  locations?: { path: string; symbol?: string; anchor?: string }[];
}
const KEY = JSON.parse(readFileSync(path.join(ROOT, 'examples/training-repository/answer-key.json'), 'utf8')) as { snapshots: Record<string, string>; items: KeyItem[] };
const itemsOf = (pattern: RegExp): KeyItem[] => KEY.items.filter((item) => pattern.test(item.id));
const locationsOf = (item: KeyItem): { path: string; symbol?: string; anchor?: string }[] => item.locations ?? (item.location === undefined ? [] : [item.location]);

/** The domains the answer key's service, flow and doc items describe: the name a reader uses and the items behind it. */
const KEY_DOMAINS = [
  { slug: 'ordering', title: 'Ordering', service: 'orders', items: itemsOf(/^(service|flow)\.orders(\.|$)/), useCase: 'uc-1' },
  { slug: 'payments', title: 'Payments', service: 'payments', items: itemsOf(/^(service|flow)\.payments(\.|$)/), useCase: 'uc-2' },
];

let owner: DatabaseOwner;
let store: GraphStore;
let view: GraphView;
let repository: string;
let scratch: string;
let kept = false;

beforeAll(async () => {
  const fixture = process.env['MADARCH_WRITER_FIXTURE'];
  if (fixture !== undefined && fixture !== '') {
    kept = true;
    mkdirSync(fixture, { recursive: true });
    scratch = fixture;
  } else {
    scratch = mkdtempSync(path.join(tmpdir(), 'madarch-writer-'));
  }
  repository = path.join(scratch, 'repository');
  if (!existsSync(path.join(repository, '.git'))) execFileSync('node', [GENERATOR, repository], { stdio: 'ignore' });
  owner = createPGliteDatabaseOwner({ btreeGist: true, path: path.join(scratch, 'store') });
  store = createGraphStore(owner);
  await owner.ready;
  await store.createSchema();
  await fillGraph({ owner, store, repository, extractors: TREE_EXTRACTORS, owners: OWNERS, history: HISTORY_EXTRACTOR, snapshots: KEY.snapshots });
  view = await GraphView.open(owner, store);
}, 1_800_000);

afterAll(async () => {
  await owner?.close();
  if (!kept && scratch !== undefined) rmSync(scratch, { recursive: true, force: true });
}, 120_000);

// ---------------------------------------------------------------------------------------------
// The scripted fake agent
// ---------------------------------------------------------------------------------------------

/** A tool call whose answer must be what the unit's contract says; the fake stops the unit on any surprise. */
async function call(request: UnitRequest, tool: string, args: Record<string, unknown> = {}): Promise<ToolAnswer> {
  return await request.tools.call(tool, args);
}

/** The graph key of a place the key names: the symbol when the graph has it, otherwise the file. */
async function groundOf(request: UnitRequest, place: { path: string; symbol?: string }): Promise<string> {
  const file = `code.file:${place.path}`;
  const name = place.symbol?.replace(/^(export )?(async )?(func|function|class|interface|type|const)\s+(\([^)]*\)\s*)?/, '').match(/[A-Za-z_][A-Za-z0-9_]*/)?.[0];
  if (name === undefined) return file;
  const found = await call(request, 'find_nodes', { kind: 'code.symbol', text: `${place.path}#`, limit: 40 });
  const nodes = (found.answer as { nodes: { key: string; label: string }[] }).nodes;
  const hit = nodes.find((n) => n.label === name || n.key.endsWith(`#${name}`) || n.key.endsWith(`.${name}`));
  return hit !== undefined && !/\s/.test(hit.key) ? hit.key : file;
}

/** A statement of the key as grounded sentences: every sentence ends with the same footnote. */
function sentences(statement: string, label: string): string {
  const parts = statement.replace(/\s+/g, ' ').trim().split(/(?<=[.!?])\s+/);
  return parts.map((part) => `${/[.!?]$/.test(part) ? part : `${part}.`}[^${label}]`).join(' ');
}

async function evidenceFor(request: UnitRequest, item: KeyItem): Promise<string[]> {
  const grounds: string[] = [];
  for (const place of locationsOf(item)) {
    if (item.evidenceClass === 'document-fact') {
      const anchor = place.anchor === undefined ? undefined : slugOf(place.anchor.replace(/\.$/, ''));
      if (anchor !== undefined) grounds.push(`doc:${place.path}#${anchor}`);
    } else {
      grounds.push(await groundOf(request, place));
    }
  }
  return [...new Set(grounds)];
}

const footnote = (label: string, grounds: readonly string[]): string => `[^${label}]: ${grounds.map((g) => `[${g.replace(/^.*[:#/]/, '') || g}](madarch:${g})`).join(', ')}`;

interface Script {
  /** Pages the fake sends before the right one, to show a refusal reaches the agent. */
  readonly firstAttemptSpoiled?: boolean;
  /** Write a paragraph of plain names the core must link (madarch-ztyq.8). */
  readonly mentions?: boolean;
}

function productScript(script: Script = {}): (request: UnitRequest) => Promise<void> {
  return async (request) => {
    await call(request, 'overview');
    const vision = await call(request, 'read_file', { path: 'docs/vision.md' });
    expect((vision.answer as { sectionAnchors: string[] }).sectionAnchors).toContain('users');
    await call(request, 'read_file', { path: 'docs/requirements.md' });
    const services = await call(request, 'find_nodes', { kind: 'code.service' });
    const keys = (services.answer as { nodes: { key: string }[] }).nodes.map((n) => n.key);
    const statements = [...itemsOf(/^stack\.passport$/), ...itemsOf(/^doc\.vision$/), ...itemsOf(/^doc\.use-cases$/), ...itemsOf(/^architecture\.composition-root$/)];
    const body: string[] = ['## What the product is', ''];
    const notes: string[] = [];
    for (const [index, item] of statements.entries()) {
      const label = String(index + 1);
      body.push(sentences(item.expectedWikiStatement, label), '');
      notes.push(footnote(label, await evidenceFor(request, item)));
    }
    body.push('## Domains', '');
    for (const domain of KEY_DOMAINS) body.push(`- [${domain.title}](madarch:domain:${domain.slug}) is implemented by the [${domain.service} service](madarch:code.service:${domain.service}).[^${domain.slug}]`);
    for (const domain of KEY_DOMAINS) notes.push(footnote(domain.slug, [`code.service:${domain.service}`, `doc:docs/requirements.md#${domain.useCase}`]));
    body.push('', 'See also the services: ' + keys.map((k) => `[${k.replace('code.service:', '')}](madarch:${k})`).join(', ') + '.');
    if (script.mentions === true) {
      // Plain prose as an agent writes it: the names are not links, and the core must make them links.
      body.push('', '## Stack', '', 'The shop stores carts in Postgres and publishes to Kafka through the outbox.[^stack]', 'UC-1 and BR-3 govern the work, and the Outbox and Capture terms explain them.[^terms]', '');
      notes.push(footnote('stack', ['code.service:orders']));
      notes.push(footnote('terms', ['doc:docs/requirements.md#uc-1']));
    }
    const page = ['---', 'id: product:training-shop', 'kind: product', 'title: Training shop', 'relates:', ...keys.map((k) => `  - ${k}`), 'producer: agent', 'sources: [docs/vision.md, docs/requirements.md]', '---', '', ...body, '', ...notes].join('\n');
    const domains = KEY_DOMAINS.map((d) => ({ slug: d.slug, title: d.title, summary: `${d.title} is what the ${d.service} service does for a shopper.`, evidence: [`code.service:${d.service}`, `doc:docs/requirements.md#${d.useCase}`] }));
    if (script.firstAttemptSpoiled) {
      const refused = await call(request, 'write_page', { markdown: `${page}\n\nThe shop is fast.`, domains });
      expect(refused.isError).toBe(true);
    }
    const written = await call(request, 'write_page', { markdown: page, domains });
    expect(written.isError).toBe(false);
  };
}

function domainScript(spoil: boolean): (request: UnitRequest, domain: (typeof KEY_DOMAINS)[number]) => Promise<void> {
  return async (request, domain) => {
    await call(request, 'get_node', { key: `code.service:${domain.service}` });
    await call(request, 'neighbors', { key: `code.service:${domain.service}`, direction: 'out' });
    // The code the domain is carried out by: functions of the service, read with the writer's own tool, and each
    // grounded where a reader of the developer section looks for it.
    const found = await call(request, 'find_nodes', { kind: 'code.symbol', text: `services/${domain.service}/`, limit: 6 });
    const functions = (found.answer as { nodes: { key: string }[] }).nodes.map((node) => node.key).filter((key) => !/\s/.test(key)).slice(0, 2).map((key) => ({ target: key }));
    const scenario: { text: string; grounds: string[] }[] = [];
    for (const item of domain.items) {
      const grounds = await evidenceFor(request, item);
      const business = grounds.filter((ground) => !ground.startsWith('code.') || ground.startsWith('code.service:'));
      scenario.push({ text: item.expectedWikiStatement, grounds: business.length === 0 ? [`code.service:${domain.service}`] : business });
    }
    const useCase = `doc:docs/requirements.md#${domain.useCase}`;
    const fields = {
      title: domain.title,
      participants: [{ text: `${domain.title} is what the ${domain.service} service does for a shopper.`, grounds: [`code.service:${domain.service}`, useCase] }],
      mainScenario: scenario.length === 0 ? [{ text: `${domain.title} has a main scenario its documents tell.`, grounds: [useCase] }] : scenario,
      developer: { ...(functions.length === 0 ? {} : { functions }), notes: [] },
    };
    if (spoil) {
      // A statement with no ground and a place the graph does not hold: both come back to the agent, and nothing is written.
      const ungrounded = await call(request, 'write_page', { fields: { ...fields, participants: [...fields.participants, { text: 'The domain is very fast.', grounds: [] }] } });
      expect(ungrounded.isError).toBe(true);
      expect((ungrounded.answer as { refused: { rule: string }[] }).refused.map((rule) => rule.rule)).toEqual(['field-ungrounded']);
      const missing = await call(request, 'write_page', { fields: { ...fields, developer: { ...fields.developer, functions: [{ target: `code.symbol:services/${domain.service}/src/nope.ts#Nothing` }] } } });
      expect(missing.isError).toBe(true);
      expect((missing.answer as { refused: { rule: string }[] }).refused.map((rule) => rule.rule)).toEqual(['unresolved-place']);
    }
    const written = await call(request, 'write_page', { fields });
    expect(written.isError).toBe(false);
  };
}

/** Gives the scratch product the starter set and declares the overview page kind this test needs. */
function declareOverview(folder: string): void {
  mkdirSync(join(folder, 'docs'), { recursive: true });
  seedStarterSet(folder);
  const file = join(folder, KINDS_FILE);
  const manifest = parseDocument(readFileSync(file, 'utf8'));
  manifest.setIn(['kinds', 'overview'], { template: 'templates/product.md', source: 'markdown', file: 'docs/overview.md', origin: 'agent', labels: { en: { one: 'Overview', many: 'Overviews' } } });
  writeFileSync(file, manifest.toString());
}

interface Run {
  report: WriterReport;
  pages: Map<string, string>;
  prompts: Map<string, string>;
  /** Every prompt that carried an editorial revision request, in the order the writer asked. */
  revisionPrompts: string[];
  /** Every unit outcome the run announced, in order. */
  unitOutcomes: UnitOutcome[];
}

// The editorial pass asks a unit for revisions after its page is accepted; the run hands its judge the page.
// ---------------------------------------------------------------------------------------------

/** The target of the first Markdown link whose label is exactly `label`; fails when the page has none. */
function linkTarget(markdown: string, label: string): string {
  const at = markdown.indexOf(`[${label}](madarch:`);
  if (at < 0) throw new Error(`the page has no link labelled ${label}: ${JSON.stringify(markdown.slice(0, 400))}`);
  const from = at + label.length + 3;
  const to = markdown.indexOf(')', from);
  const target = markdown.slice(from, to);
  return target.startsWith('madarch:') ? target.slice('madarch:'.length) : target;
}

const MENTION_NAMES: readonly MentionName[] = [
  { name: 'UC-1', target: 'doc:docs/requirements.md#uc-1', caseSensitive: true },
  { name: 'BR-3', target: 'doc:docs/requirements.md#br-3', caseSensitive: true },
  { name: 'Outbox', target: 'doc:docs/glossary.md#outbox', caseSensitive: true },
  { name: 'Capture', target: 'doc:docs/glossary.md#capture', caseSensitive: true },
];

async function run(options: { spoilProduct?: boolean; spoilDomains?: boolean; output?: string; refuseRevisions?: boolean; mentions?: boolean; editorial?: { judge?: EditorialJudge; maxRequestsPerPage?: number; journal?: Journal; skipReason?: string } } = {}): Promise<Run> {
  const sink = memorySink();
  const prompts = new Map<string, string>();
  const revisionPrompts: string[] = [];
  const unitOutcomes: UnitOutcome[] = [];
  const refusing = new Set<string>();
  const product = productScript({ ...(options.spoilProduct === true ? { firstAttemptSpoiled: true } : {}), ...(options.mentions === true ? { mentions: true } : {}) });
  const domain = domainScript(options.spoilDomains === true);
  const agent: UnitAgent = {
    run: async (request) => {
      prompts.set(request.id, request.prompt);
      const revision = request.prompt.includes('## The editorial pass asked for these revisions');
      if (revision) revisionPrompts.push(request.prompt);
      if (options.refuseRevisions === true && (revision || refusing.has(request.id))) {
        // The agent cannot answer the revision: every attempt is a page the contract refuses, and the unit keeps trying
        // until its bound is spent, exactly as an editing model that will not follow the request does.
        refusing.add(request.id);
        await request.tools.call('write_page', {});
        return;
      }
      if (request.id === 'product:training-shop') await product(request);
      else if (request.id.startsWith('overview:')) {
        await request.tools.call('write_page', { markdown: '---\nid: overview:training-shop\nkind: overview\ntitle: Training shop\nrelates: []\nproducer: agent\nsources: []\n---\n\n## What the product is\n\nThe shop takes orders.[^1]\n\n[^1]: [orders](madarch:code.service:orders)\n' });
      } else await domain(request, KEY_DOMAINS.find((d) => `domain:${d.slug}` === request.id)!);
    },
  };
  const report = await runWriter({ owner, store, repository, output: options.output ?? path.join(scratch, 'unused-output'), productName: 'Training shop', agent, sink, onUnit: (outcome) => unitOutcomes.push(outcome), ...(options.mentions === true ? { mentions: MENTION_NAMES } : {}), ...(options.editorial === undefined ? {} : { editorial: options.editorial }) });
  return { report, pages: sink.pages, prompts, revisionPrompts, unitOutcomes };
}

// ---------------------------------------------------------------------------------------------
// What was written
// ---------------------------------------------------------------------------------------------

let first: Run;
let second: Run;

describe('the writer over the training repository', () => {

  test('the filesystem sink refuses path traversal and a symlinked source directory', async () => {
    const root = mkdtempSync(join(tmpdir(), 'madarch-localized-sink-'));
    const outside = mkdtempSync(join(tmpdir(), 'madarch-localized-outside-'));
    try {
      await expect(fsSink(root).write('docs/sources/../escape.md', 'not allowed')).rejects.toThrow();
      mkdirSync(join(root, 'docs'), { recursive: true });
      symlinkSync(outside, join(root, 'docs', 'sources'));
      await expect(fsSink(root).write('docs/sources/doc.term/abc.md', 'not allowed')).rejects.toThrow();
      expect(existsSync(join(outside, 'doc.term', 'abc.md'))).toBe(false);
    } finally {
      rmSync(root, { recursive: true, force: true });
      rmSync(outside, { recursive: true, force: true });
    }
  });

  test('a localized-source unit writes the statement with fixed source identity and provenance', async () => {
    const sourceText = readFileSync(path.join(ROOT, 'examples/training-repository/template/docs/requirements.md'), 'utf8');
    const sourceLine = sourceText.split('\n').find((line) => line.includes('order'))!;
    const entity = { id: 'doc:docs/requirements.md#doc-section:2', kind: 'doc.requirement', title: 'Order requirement', identifier: 'UC-1', repo: null, path: 'docs/requirements.md', anchor: 'localized-test', aliases: ['localized-test'], line: 1, endLine: 1, text: sourceLine, stableId: 'doc-section:2', semantics: 'quality' as const, pass: 'metadata' as const, headingPath: ['Requirements'] };
    expect(entity.text).not.toBe('');
    const sink = memorySink();
    const sourcePath = localizedSourcePath(entity);
    const tools = new UnitTools(view, { kind: 'localized-source', id: entity.id, path: sourcePath, entity, sourceLanguage: 'en', language: 'ru' }, sink);
    const malformed = await tools.call('write_localized_source', { statement: '## In the source\nforged source text' });
    expect(malformed.isError).toBe(true);
    const mostlyWrong = await tools.call('write_localized_source', { statement: 'This paragraph is still mostly English. тест' });
    expect(mostlyWrong.isError).toBe(true);
    expect((mostlyWrong.answer as { error: { code: string } }).error.code).toBe('wrong-language');
    const answer = await tools.call('write_localized_source', { statement: 'Не входи.' });
    expect(answer.isError).toBe(false);
    expect(tools.outcome().status).toBe('written');
    const markdown = sink.pages.get(sourcePath)!;
    expect(markdown).toContain(`entity: ${entity.id}`);
    expect(markdown).toContain('source-document: docs/requirements.md');
    expect(markdown).toContain(entity.text);
    expect(markdown).toContain('Не входи.');
  });
  beforeAll(async () => {
    first = await run({ spoilProduct: true, spoilDomains: true });
    second = await run();
  }, 600_000);

  test('the editorial pass runs on the filled training product after the page batch and after the overview, and journals every request at its point', async () => {
    const journal = memoryJournal('run-editorial-training');
    const calls: string[][] = [];
    const judge: EditorialJudge = {
      async judge(pack) {
        calls.push(pack.pages.map((page) => page.path));
        const page = pack.pages.find((held) => held.statements.length > 0);
        if (page === undefined) return { requests: [] };
        return { requests: [{ page: page.path, passage: page.statements[0]!.id, change: 'Say this so a newcomer can follow it.', why: 'The first sentence assumes the rest of the page.' }] };
      },
    };
    const output = join(scratch, 'editorial-training-product');
    declareOverview(output);
    const editorial = await run({ output, editorial: { journal, maxRequestsPerPage: 2, judge } });
    // The writer's own report says both points ran; the fake judge saw the batch (product + domains)
    // before the overview, then the complete set.
    expect(editorial.report.editorialPasses.map((pass) => pass.point)).toEqual(['batch', 'overview']);
    expect(editorial.report.editorialPasses[0]!.pages).not.toContain('docs/overview.md');
    expect(editorial.report.editorialPasses[1]!.pages).toContain('docs/overview.md');
    expect(calls).toHaveLength(2);
    expect(calls[0]!.some((page) => page.startsWith('docs/domains/'))).toBe(true);
    expect(calls[1]).toEqual(expect.arrayContaining([...calls[0]!]));
    expect(editorial.report.editorialProblems).toEqual([]);
    // Each point's requests are journal entries tagged with the point, so a revision is never hidden.
    const at = (point: string) => journal.records.filter((record) => record.kind === 'revision-request' && (record.arguments as { point?: string }).point === point);
    expect(at('batch').length).toBeGreaterThan(0);
    expect(at('overview').length).toBeGreaterThan(0);
    // The fake judge was asked at both points; the deterministic findings lead the bound, so these
    // records prove the pass ran and journalled at each point, and test/writer-editorial.test.ts
    // proves the editing role's own requests are bounded and journalled.
    expect(editorial.report.revisionRequests.length).toBeGreaterThanOrEqual(2);
  }, 240_000);

  test('an unassigned editing role records its findings and leaves every page exactly as the writer wrote it', async () => {
    const baselineOutput = join(scratch, 'editorial-skipped-baseline');
    declareOverview(baselineOutput);
    const baseline = await run({ output: baselineOutput });
    const skippedOutput = join(scratch, 'editorial-skipped-product');
    declareOverview(skippedOutput);
    const skipped = await run({ output: skippedOutput, editorial: { skipReason: 'the editing role is not assigned', maxRequestsPerPage: 2 } });
    // The checks still run and their requests are reported, but no model is asked and no page is reworked.
    expect(skipped.report.revisionRequests.length).toBeGreaterThan(0);
    expect(skipped.revisionPrompts).toEqual([]);
    expect([...skipped.pages.keys()]).toEqual([...baseline.pages.keys()]);
    for (const [page, text] of baseline.pages) expect(skipped.pages.get(page)).toBe(text);
    expect(skipped.unitOutcomes.filter((outcome) => outcome.unit === 'domain:ordering').map((outcome) => outcome.status)).toEqual(['written']);
    expect(skipped.report.ok).toBe(true);
  }, 240_000);

  test('a revision the agent refuses leaves the page and the unit that wrote it as they stood', async () => {
    const output = join(scratch, 'editorial-refused-product');
    declareOverview(output);
    let asked = false;
    const judge: EditorialJudge = {
      async judge(pack) {
        if (asked) return { requests: [] };
        const page = pack.pages.find((held) => held.path === 'docs/domains/ordering.md' && held.statements.length > 0);
        if (page === undefined) return { requests: [] };
        asked = true;
        return { requests: [{ page: page.path, passage: page.statements[0]!.id, change: 'Say this so a newcomer can follow it.', why: 'The first sentence assumes the rest of the page.' }] };
      },
    };
    const refused = await run({ output, editorial: { judge, maxRequestsPerPage: 1 }, refuseRevisions: true });
    // The revision was asked for and refused; the page the unit wrote before the pass is still its page.
    expect(refused.revisionPrompts.length).toBeGreaterThan(0);
    expect(refused.revisionPrompts[0]).toContain('The product unit declared this domain: Ordering is what the orders service does for a shopper.');
    expect(refused.report.domains.map((domain) => [domain.unit, domain.status])).toEqual([['domain:ordering', 'written'], ['domain:payments', 'written']]);
    expect(refused.report.ok).toBe(true);
    expect(refused.report.editorialProblems.some((problem) => problem.includes('docs/domains/ordering.md'))).toBe(true);
    // The revision is not the page unit's attempt: it does not announce a second, failed outcome for the same unit.
    expect(refused.unitOutcomes.filter((outcome) => outcome.unit === 'domain:ordering').map((outcome) => outcome.status)).toEqual(['written']);
  }, 240_000);

  test('runs one unit for the product and one per domain, in that order, and writes their three files', () => {
    expect(JSON.stringify([first.report.product.refusals, ...first.report.domains.map((d) => d.refusals)])).toBe('[[],[],[]]');
    expect(first.report.ok).toBe(true);
    expect(first.report.units).toBe(3);
    expect(first.report.product.unit).toBe('product:training-shop');
    expect(first.report.domains.map((d) => d.unit)).toEqual(['domain:ordering', 'domain:payments']);
    expect([...first.pages.keys()].sort()).toEqual(['docs/domains/ordering.md', 'docs/domains/payments.md', 'docs/product.md']);
    expect([...first.prompts.keys()]).toEqual(['product:training-shop', 'domain:ordering', 'domain:payments']);
  });

  test('an agent writes plain names, and the core links every mention to the page the product knows', async () => {
    const mentioned = await run({ mentions: true });
    const page = mentioned.pages.get('docs/product.md')!;
    // A document identifier and a glossary term keep the address of their page; a graph label names its node.
    expect(linkTarget(page, 'UC-1')).toBe('doc:docs/requirements.md#uc-1');
    expect(linkTarget(page, 'BR-3')).toBe('doc:docs/requirements.md#br-3');
    expect(linkTarget(page, 'Outbox')).toBe('doc:docs/glossary.md#outbox');
    expect(linkTarget(page, 'Capture')).toBe('doc:docs/glossary.md#capture');
    for (const label of ['Postgres', 'outbox']) {
      const target = linkTarget(page, label);
      expect(target.startsWith('code.')).toBe(true);
      expect(await view.graphKey(target)).toBe(true);
    }
    // A heading is not prose: the section title keeps the agent's text.
    expect(page).toContain('\n## Stack\n');
    // The page states the paragraph it wrote, and each sentence keeps its ground.
    expect(page).toContain('stores carts in [Postgres]');
    // `Kafka` names both the broker and its compose service and the page has no evidence which it means:
    // an ambiguous mention stays plain (madarch-ztyq.8, review 202).
    expect(page).toContain('publishes to Kafka');
    expect(page).not.toContain('[Kafka](madarch:');
    expect(page).toContain('through the [outbox]');
  }, 600_000);

  test('stores the text files in the graph before any unit runs, and says what it left out', async () => {
    const content = first.report.content;
    expect(content.stored).toBeGreaterThan(50);
    // Binary or oversized files are named with a reason, never dropped silently.
    for (const skipped of content.skipped) expect(skipped.reason.length).toBeGreaterThan(0);
    const readme = readFileSync(path.join(repository, 'docs/vision.md'), 'utf8');
    expect(await view.fileText('docs/vision.md')).toBe(readme);
  });

  test('the product unit declares the domains the answer key describes: payments and ordering, each with evidence that resolves', async () => {
    const declared = first.report.product.domains;
    expect(declared.map((d: DomainDeclaration) => d.slug)).toEqual(['ordering', 'payments']);
    for (const domain of KEY_DOMAINS) {
      // The key's service, flow and doc items for the domain all point at code and documents the graph holds.
      expect(domain.items.length).toBeGreaterThan(0);
      for (const item of domain.items) {
        for (const place of locationsOf(item)) {
          expect(await view.graphKey(`code.file:${place.path}`)).toBe(true);
          expect(place.path.startsWith(`services/${domain.service}/`)).toBe(true);
        }
      }
      const declaration = declared.find((d: DomainDeclaration) => d.slug === domain.slug)!;
      for (const target of declaration.evidence) {
        if (target.startsWith('doc:')) {
          const [file, anchor] = target.slice(4).split('#');
          expect(await view.docSection(file!, anchor!)).toBe(true);
        } else {
          expect(await view.graphKey(target)).toBe(true);
        }
      }
    }
    const useCases = KEY.items.find((i) => i.id === 'doc.use-cases')!;
    for (const id of useCases.expectedWikiStatement.match(/UC-\d/g) ?? []) expect(await view.docSection('docs/requirements.md', id.toLowerCase())).toBe(true);
  });

  test('every page follows the format: front matter, then statements each ending in footnotes, then the footnotes', () => {
    for (const [file, markdown] of first.pages) {
      const match = /^---\n([^]*?)\n---\n\n([^]*)$/.exec(markdown);
      expect(match).not.toBeNull();
      const front = parseYaml(match![1]!) as Record<string, unknown>;
      expect(Object.keys(front)).toEqual(['id', 'kind', 'title', 'relates', 'producer', 'sources', 'written-at']);
      // the page records what it was written from: the training repository's commit and branch (the fixture has no origin)
      expect(front['written-at']).toEqual([{ repository: 'repository', commit: execFileSync('git', ['rev-parse', 'HEAD'], { cwd: repository, encoding: 'utf8' }).trim(), branch: execFileSync('git', ['branch', '--show-current'], { cwd: repository, encoding: 'utf8' }).trim() }]);
      expect(front['producer']).toBe('agent');
      const isProduct = file === 'docs/product.md';
      expect(front['kind']).toBe(isProduct ? 'product' : 'domain');
      expect(front['id']).toBe(isProduct ? 'product:training-shop' : `domain:${path.basename(file, '.md')}`);
      expect(markdown.endsWith('\n')).toBe(true);
      const lines = match![2]!.split('\n');
      const definitions = lines.filter((l) => /^\[\^[a-z0-9-]+\]: /.test(l));
      // one footnote per statement, each named (not numbered) and unique on the page
      const names = definitions.map((l) => l.slice(2, l.indexOf(']:')));
      expect(new Set(names).size).toBe(names.length);
      for (const name of names) expect(name).toMatch(/^[a-z][a-z0-9]*(-[a-z0-9]+)*$/);
      // A place of the developer section is a bullet that is a link to its key, with the footnote of its ground: it
      // names a place, it states nothing (madarch-ztyq.6).
      const text = lines.filter((l) => l.trim() !== '' && !/^\[\^[a-z0-9-]+\]: /.test(l) && !l.startsWith('#') && !/^(- )?See also/.test(l) && !/^- \[[^\]]+\]\(madarch:[^)]+\)(\[\^[a-z0-9-]+\])?$/.test(l));
      expect(text.length).toBeGreaterThan(0);
      for (const line of text) {
        // Every statement line ends each of its sentences in footnote references.
        for (const sentence of line.replace(/^- /, '').split(/(?<=\])\s+(?=[A-Z])/)) expect(sentence).toMatch(/[.!?](\[\^[a-z0-9-]+\])+$/);
      }
    }
  });

  test('every ground of every footnote resolves: a key the graph holds at the fill, or a section the document has', async () => {
    let grounds = 0;
    for (const markdown of first.pages.values()) {
      for (const definition of markdown.split('\n').filter((l) => /^\[\^[a-z0-9-]+\]: /.test(l))) {
        for (const target of [...definition.matchAll(/\]\(madarch:([^)]+)\)/g)].map((m) => m[1]!)) {
          grounds += 1;
          if (target.startsWith('doc:')) {
            const [file, anchor] = target.slice(4).split('#');
            const text = readFileSync(path.join(repository, file!), 'utf8').toLowerCase();
            // Independent of the writer's own anchor index: the id appears in the document, or a heading or bold phrase slugs to the anchor.
            const slugs = [...text.matchAll(/^#+\s+(.*)$|\*\*([^*]+)\*\*/gm)].map((m) => slugOf((m[1] ?? m[2])!.replace(/\.$/, '')));
            expect(text.includes(anchor!) || slugs.includes(anchor!)).toBe(true);
          } else {
            const rows = (await owner.run((tx) => tx.query(`SELECT 1 FROM node_version WHERE properties->>'recordKey' = $1 AND recorded_to = 'infinity' LIMIT 1`, [target]))).rows;
            expect(rows.length).toBe(1);
          }
        }
      }
    }
    expect(grounds).toBeGreaterThan(20);
  });

  test('every entity link in the text is a key of the graph, a document section or a declared domain', async () => {
    const declared = new Set(first.report.product.domains.map((d: DomainDeclaration) => `domain:${d.slug}`));
    for (const markdown of first.pages.values()) {
      const body = markdown.split('\n').filter((l) => !/^\[\^[a-z0-9-]+\]: /.test(l)).join('\n');
      for (const target of [...body.matchAll(/\]\(madarch:([^)]+)\)/g)].map((m) => m[1]!)) {
        if (target.startsWith('domain:')) expect(declared.has(target)).toBe(true);
        else if (target.startsWith('doc:')) expect(await view.docSection(target.slice(4).split('#')[0]!, target.split('#')[1]!)).toBe(true);
        else expect(await view.graphKey(target)).toBe(true);
      }
    }
  });

  test('a domain page names its own service and the code of the key\'s flow items among its relations and grounds', () => {
    for (const domain of KEY_DOMAINS) {
      const page = first.pages.get(`docs/domains/${domain.slug}.md`)!;
      const front = parseYaml(page.split('\n---\n')[0]!.slice(4)) as { relates: string[] };
      expect(front.relates).toContain(`code.service:${domain.service}`);
      const grounds = first.report.domains.find((d) => d.unit === `domain:${domain.slug}`)!.grounds;
      // The key's flow items for the domain are served by files under the service, so the page grounds code there.
      expect(grounds.some((g) => g.startsWith('code.') && g.includes(`services/${domain.service}/`))).toBe(true);
      expect(grounds.some((g) => g === `doc:docs/requirements.md#${domain.useCase}`)).toBe(true);
    }
  });

  test('a refusal comes back to the agent and the unit goes on: nothing was written until the page was right', () => {
    expect(first.report.product.writeAttempts).toBe(2);
    for (const domain of first.report.domains) expect(domain.writeAttempts).toBe(3);
    expect(second.report.product.writeAttempts).toBe(1);
  });

  test('the same graph, the same prompts and the same answers give the same files, byte for byte', () => {
    expect([...second.pages.entries()].sort()).toEqual([...first.pages.entries()].sort());
    expect([...second.prompts.entries()]).toEqual([...first.prompts.entries()]);
    expect(second.report.content.unchanged).toBe(true);
    expect(second.report.content.stored).toBe(first.report.content.stored);
  });

  test('the prompts hold the format and the graph, and no file content', () => {
    for (const [unit, prompt] of first.prompts.entries()) {
      // A domain page is written by the core from its unit's fields (madarch-ztyq.6): its prompt carries what the
      // core writes for it instead of the page format, and the graph the same way.
      if (unit.startsWith('domain:')) expect(prompt).toContain('## What the core writes for you');
      else expect(prompt).toContain('Every sentence that states something ends with a footnote');
      expect(prompt).toContain('code.service:orders');
      expect(prompt).not.toContain('CREATE TABLE');
      expect(prompt.length).toBeLessThan(20_000 * 4);
    }
    expect(first.prompts.get('domain:payments')!).toContain('Payments');
  });
});

// ---------------------------------------------------------------------------------------------
// The tools and their refusals
// ---------------------------------------------------------------------------------------------

describe('the unit tools', () => {
  const productSpec: UnitSpec = { kind: 'product', id: 'product:training-shop', path: 'docs/product.md', name: 'Training shop' };
  // The page format is the same for every kind (`src/writer/format.ts`), and these cases judge the format, not a
  // domain: a validation unit writes its page as Markdown, so it is the vehicle here. A domain page is written from
  // its fields and is judged in test/writer-domain-pages.test.ts (madarch-ztyq.6).
  const validationSpec = (scope: string): UnitSpec => ({ kind: 'validation', id: `validation:${scope}`, path: `docs/validation/${scope}.md`, name: 'Training shop' });
  const known: DomainDeclaration[] = [{ slug: 'payments', title: 'Payments', summary: 'Payments.', evidence: ['code.service:payments'] }];
  const header = (scope: string): string => `---\nid: validation:${scope}\nkind: validation\ntitle: Payments\nrelates:\n  - code.service:payments\nproducer: agent\nsources: []\n---\n\n`;
  const grounded = 'Payments run in the payments service.[^1]\n\n[^1]: [payments](madarch:code.service:payments)\n';

  function session(spec: UnitSpec = validationSpec('payments'), bounds = DEFAULT_UNIT_BOUNDS, extras: ConstructorParameters<typeof UnitTools>[6] = {}) {
    const sink = memorySink();
    return { sink, tools: new UnitTools(view, spec, sink, known, bounds, [], extras) };
  }

  test('an agent has the fourteen tools that answer questions, and no way to reach the repository, a shell or the disk', () => {
    expect(WRITER_TOOLS.map((t) => t.name)).toEqual(['overview', 'find_nodes', 'get_node', 'neighbors', 'read_file', 'get_symbol', 'get_context', 'trace_flow', 'get_document_sections', 'search_pages', 'get_page', 'search_questions', 'write_page', 'ask_question']);
    const { tools } = session();
    expect(tools.tools.map((t) => t.name)).toEqual(['overview', 'find_nodes', 'get_node', 'neighbors', 'read_file', 'get_symbol', 'get_context', 'trace_flow', 'get_document_sections', 'search_pages', 'get_page', 'search_questions', 'write_page', 'ask_question']);
  });

  test('a file is read from the graph in bounded numbered lines, and a missing or unlisted file is an error', async () => {
    const { tools } = session();
    const answer = await tools.call('read_file', { path: 'docs/requirements.md', startLine: 3, endLine: 5 });
    expect(answer.isError).toBe(false);
    const text = readFileSync(path.join(repository, 'docs/requirements.md'), 'utf8').split('\n');
    const body = answer.answer as { text: string; startLine: number; endLine: number; totalLines: number; sectionAnchors: string[] };
    expect(body.text).toBe([3, 4, 5].map((n) => `${n}: ${text[n - 1]}`).join('\n'));
    expect(body.sectionAnchors).toContain('uc-1');
    const long = await tools.call('read_file', { path: 'docs/requirements.md', startLine: 1, endLine: 5000 });
    expect((long.answer as { text: string }).text.split('\n').length).toBeLessThanOrEqual(200);
    const missing = await tools.call('read_file', { path: '../../etc/passwd' });
    expect(missing.isError).toBe(true);
    expect((missing.answer as { error: { code: string } }).error.code).toBe('no-content');
    expect(tools.outcome().filesRead).toEqual(['docs/requirements.md']);
  });

  test('find_nodes pages in key order and node reads show the edges', async () => {
    const { tools } = session();
    const page = await tools.call('find_nodes', { kind: 'code.service' });
    expect((page.answer as { nodes: { key: string }[] }).nodes.map((n) => n.key)).toEqual(['code.service:checkout', 'code.service:orders', 'code.service:payments', 'code.service:promotions']);
    const some = await tools.call('find_nodes', { kind: 'code.symbol', limit: 3 });
    const { nodes, next } = some.answer as { nodes: { key: string }[]; next: string | null };
    expect(nodes).toHaveLength(3);
    expect(next).toBe(nodes[2]!.key);
    const following = await tools.call('find_nodes', { kind: 'code.symbol', limit: 3, after: next });
    expect((following.answer as { nodes: { key: string }[] }).nodes[0]!.key > nodes[2]!.key).toBe(true);
    const node = await tools.call('get_node', { key: 'code.service:payments' });
    expect((node.answer as { kind: string }).kind).toBe('code.service');
    expect((await tools.call('get_node', { key: 'code.service:nothing' })).isError).toBe(true);
    expect((await tools.call('neighbors', { key: 'code.service:payments', direction: 'sideways' })).isError).toBe(true);
  });

  test('a statement with no footnote is refused, and nothing is written', async () => {
    const { tools, sink } = session();
    const answer = await tools.call('write_page', { markdown: `${header('payments')}Payments run in the payments service.[^1] Refunds take thirty days.\n\n[^1]: [payments](madarch:code.service:payments)\n` });
    expect(answer.isError).toBe(true);
    const refused = (answer.answer as { refused: { rule: string; message: string }[]; attemptsLeft: number }).refused;
    expect(refused.map((r) => r.rule)).toEqual(['ungrounded-statement']);
    expect(refused[0]!.message).toContain('Refunds take thirty days.');
    expect((answer.answer as { attemptsLeft: number }).attemptsLeft).toBe(4);
    expect(sink.pages.size).toBe(0);
    expect(tools.outcome().status).toBe('failed');
  });

  test('a ground that does not resolve is refused, whether a key or a document section', async () => {
    const { tools, sink } = session();
    const key = await tools.call('write_page', { markdown: `${header('payments')}Payments run in the payments service.[^1]\n\n[^1]: [x](madarch:code.symbol\u003aservices/payments/src/missing.ts#Missing)\n` });
    expect((key.answer as { refused: { rule: string; message: string }[] }).refused.map((r) => r.rule)).toEqual(['unresolved-ground']);
    const section = await tools.call('write_page', { markdown: `${header('payments')}Payments run in the payments service.[^1]\n\n[^1]: [x](madarch:doc:docs/requirements.md#uc-99)\n` });
    expect((section.answer as { refused: { message: string }[] }).refused[0]!.message).toContain('has no section "uc-99"');
    expect(sink.pages.size).toBe(0);
  });

  test('a link outside the graph is refused, in the text and as a domain nobody declared', async () => {
    const { tools, sink } = session();
    const outside = await tools.call('write_page', { markdown: `${header('payments')}The [billing service](madarch:code.service:billing) charges cards.[^1]\n\n[^1]: [payments](madarch:code.service:payments)\n` });
    expect((outside.answer as { refused: { rule: string }[] }).refused.map((r) => r.rule)).toEqual(['link-outside-graph']);
    const undeclared = await tools.call('write_page', { markdown: `${header('payments')}The [shipping domain](madarch:domain:shipping) is separate.[^1]\n\n[^1]: [payments](madarch:code.service:payments)\n` });
    expect((undeclared.answer as { refused: { rule: string }[] }).refused.map((r) => r.rule)).toEqual(['link-outside-graph']);
    expect(sink.pages.size).toBe(0);
  });

  test('a page right the second time is written once, at the unit\'s own path, and a second write is refused', async () => {
    const { tools, sink } = session();
    expect((await tools.call('write_page', { markdown: `${header('payments')}Payments run.` })).isError).toBe(true);
    const written = await tools.call('write_page', { markdown: `${header('payments')}${grounded}` });
    expect(written.isError).toBe(false);
    expect([...sink.pages.keys()]).toEqual(['docs/validation/payments.md']);
    expect(tools.outcome()).toMatchObject({ status: 'written', writeAttempts: 2, refusals: [] });
    expect((await tools.call('write_page', { markdown: `${header('payments')}${grounded}` })).isError).toBe(true);
  });

  test('a revision writes the passage it was asked about and no other', async () => {
    const scope = validationSpec('payments');
    const original = `${header('payments')}Payments run in the payments service.[^1] Refunds take nine days.[^2]\n\n[^1]: [payments](madarch:code.service:payments)\n[^2]: [payments](madarch:code.service:payments)\n`;
    const revised = `${header('payments')}Payments run in the payments service.[^1] Refunds take fourteen days.[^2]\n\n[^1]: [payments](madarch:code.service:payments)\n[^2]: [payments](madarch:code.service:payments)\n`;
    const sink = memorySink();
    const first = new UnitTools(view, scope, sink, known, DEFAULT_UNIT_BOUNDS);
    expect((await first.call('write_page', { markdown: original })).isError).toBe(false);
    // The editorial pass reads the page the core wrote, whose footnote names the core chose: those names are the
    // statement ids a revision request carries.
    const written = sink.pages.get('docs/validation/payments.md')!;
    const [firstPassage, secondPassage] = statementsOfMarkdown(written).map((statement) => statement.id);
    const scoped = new UnitTools(view, scope, sink, known, DEFAULT_UNIT_BOUNDS, [], { revisionScope: { before: written, passages: [firstPassage!] } });
    const answer = await scoped.call('write_page', { markdown: revised });
    expect((answer.answer as { refused: { rule: string; message: string }[] }).refused.map((refusal) => refusal.rule)).toEqual(['revision-scope']);
    expect((answer.answer as { refused: { message: string }[] }).refused[0]!.message).toContain('docs/validation/payments.md');
    expect(sink.pages.get('docs/validation/payments.md')).toBe(written);
    // The named passage is the one the request may change: the same revision is accepted there.
    const inScope = new UnitTools(view, scope, sink, known, DEFAULT_UNIT_BOUNDS, [], { revisionScope: { before: written, passages: [secondPassage!] } });
    expect((await inScope.call('write_page', { markdown: revised })).isError).toBe(false);
    expect(sink.pages.get('docs/validation/payments.md')).toContain('fourteen days');
    // A new paragraph beside the named passage is prose the pass did not ask about, even when the named passage
    // changes too; the block count is part of the bound (madarch-ztyq.9, review 199).
    const inserted = `${header('payments')}Payments run in the payments service.[^1] Refunds take fourteen days.[^2]\n\nRefunds also need a receipt.[^3]\n\n[^1]: [payments](madarch:code.service:payments)\n[^2]: [payments](madarch:code.service:payments)\n[^3]: [payments](madarch:code.service:payments)\n`;
    const grown = new UnitTools(view, scope, sink, known, DEFAULT_UNIT_BOUNDS, [], { revisionScope: { before: written, passages: [secondPassage!] } });
    const grownAnswer = await grown.call('write_page', { markdown: inserted });
    const grownRules = (grownAnswer.answer as { refused: { rule: string }[] }).refused.map((refusal) => refusal.rule);
    expect(grownRules.length).toBeGreaterThan(0);
    expect(grownRules.every((rule) => rule === 'revision-scope')).toBe(true);
    expect(sink.pages.get('docs/validation/payments.md')).not.toContain('receipt');
  });

  test('a revision cannot swap the grounds of a passage it was not asked about', async () => {
    const scope = validationSpec('payments');
    const original = `${header('payments')}Payments run in the payments service.[^1] Orders run in the ordering service.[^2]\n\n[^1]: [payments](madarch:code.service:payments)\n[^2]: [orders](madarch:code.service:orders)\n`;
    const sink = memorySink();
    const first = new UnitTools(view, scope, sink, known, DEFAULT_UNIT_BOUNDS);
    expect((await first.call('write_page', { markdown: original })).isError).toBe(false);
    const written = sink.pages.get('docs/validation/payments.md')!;
    const [paymentsPassage, ordersPassage] = statementsOfMarkdown(written).map((statement) => statement.id);
    // Swapping two grounds leaves the multiset of definitions unchanged, but only the payments passage was named.
    const swapped = written.split('\n').map((line) => {
      if (line.startsWith(`[^${paymentsPassage}]:`)) return `[^${paymentsPassage}]: [orders](madarch:code.service:orders)`;
      if (line.startsWith(`[^${ordersPassage}]:`)) return `[^${ordersPassage}]: [payments](madarch:code.service:payments)`;
      return line;
    }).join('\n');
    const scoped = new UnitTools(view, scope, sink, known, DEFAULT_UNIT_BOUNDS, [], { revisionScope: { before: written, passages: [paymentsPassage!] } });
    const answer = await scoped.call('write_page', { markdown: swapped });
    expect((answer.answer as { refused: { rule: string; message: string }[] }).refused.map((refusal) => refusal.rule)).toEqual(['revision-scope']);
    expect((answer.answer as { refused: { message: string }[] }).refused[0]!.message).toContain('no named passage stands on it');
    expect(sink.pages.get('docs/validation/payments.md')).toBe(written);
  });

  test('a revision cannot change the shape of a passage it was not asked about', async () => {
    const scope = validationSpec('payments');
    const original = `${header('payments')}Payments run in the payments service.[^1] Orders run in the ordering service.[^2]\n\n[^1]: [payments](madarch:code.service:payments)\n[^2]: [orders](madarch:code.service:orders)\n`;
    const sink = memorySink();
    const first = new UnitTools(view, scope, sink, known, DEFAULT_UNIT_BOUNDS);
    expect((await first.call('write_page', { markdown: original })).isError).toBe(false);
    const written = sink.pages.get('docs/validation/payments.md')!;
    const [paymentsPassage] = statementsOfMarkdown(written).map((statement) => statement.id);
    // The sentence reads the same, so only the shape under it changed: a passage not named may not be rewritten.
    // The agent sends the page it would write, without the links the core adds; the pass compares the stored page,
    // which has them, with the page this draft becomes (madarch-ztyq.8).
    const changed = original.replace('Orders run in the ordering service.', 'Orders run in *the ordering service*.');
    expect(changed).not.toBe(original);
    const scoped = new UnitTools(view, scope, sink, known, DEFAULT_UNIT_BOUNDS, [], { revisionScope: { before: written, passages: [paymentsPassage!] } });
    const answer = await scoped.call('write_page', { markdown: changed });
    expect((answer.answer as { refused: { rule: string; message: string }[] }).refused.map((refusal) => refusal.rule)).toEqual(['revision-scope']);
    expect(sink.pages.get('docs/validation/payments.md')).toBe(written);
  });

  test('a page of another id is refused, so a unit cannot write another unit\'s page', async () => {
    const { tools, sink } = session(validationSpec('ordering'));
    const answer = await tools.call('write_page', { markdown: `${header('payments')}${grounded}` });
    expect((answer.answer as { refused: { message: string }[] }).refused[0]!.message).toContain('this page\'s id is "validation:ordering"');
    expect(sink.pages.size).toBe(0);
  });

  test('attempts are bounded: after the last refusal the unit has failed and nothing more is accepted', async () => {
    const { tools, sink } = session(validationSpec('payments'), { maxWriteAttempts: 2, maxCalls: 80 });
    expect((await tools.call('write_page', { markdown: `${header('payments')}Payments run.` })).isError).toBe(true);
    const last = await tools.call('write_page', { markdown: `${header('payments')}Payments run.` });
    expect((last.answer as { attemptsLeft: number; note: string }).attemptsLeft).toBe(0);
    expect(tools.finished).toBe(true);
    const after = await tools.call('write_page', { markdown: `${header('payments')}${grounded}` });
    expect((after.answer as { error: { code: string } }).error.code).toBe('no-attempts');
    expect(sink.pages.size).toBe(0);
    expect(tools.outcome()).toMatchObject({ status: 'failed', writeAttempts: 2 });
  });

  test('two writes at once cannot both be accepted', async () => {
    const { tools, sink } = session();
    const page = { markdown: `${header('payments')}${grounded}` };
    const [a, b] = await Promise.all([tools.call('write_page', page), tools.call('write_page', page)]);
    expect([a.isError, b.isError].sort()).toEqual([false, true]);
    expect(sink.pages.size).toBe(1);
    expect(tools.outcome().writeAttempts).toBe(1);
  });

  test('a unit reads documents only as Markdown: another file\'s comment lines are no section', async () => {
    expect(await view.docSection('Makefile', 'test')).toBe(false);
  });

  test('the number of tool calls is bounded too', async () => {
    const { tools } = session(validationSpec('payments'), { maxWriteAttempts: 5, maxCalls: 3 });
    for (let i = 0; i < 3; i += 1) expect((await tools.call('overview', {})).isError).toBe(false);
    const over = await tools.call('overview', {});
    expect((over.answer as { error: { code: string } }).error.code).toBe('call-limit');
    expect(tools.finished).toBe(true);
  });

  test('the product page declares its domains with evidence that must resolve, and links each of them', async () => {
    const page = (links: string): string => `---\nid: product:training-shop\nkind: product\ntitle: Training shop\nrelates: []\nproducer: agent\nsources: []\n---\n\n${links}\n\n[^1]: [payments](madarch:code.service:payments)\n`;
    const declaration = { slug: 'payments', title: 'Payments', summary: 'Payments.', evidence: ['code.service:payments'] };
    const missing = session(productSpec).tools;
    expect((await missing.call('write_page', { markdown: page('The shop takes payments.[^1]') })).isError).toBe(true);
    const unresolved = session(productSpec).tools;
    const bad = await unresolved.call('write_page', { markdown: page('The [payments](madarch:domain:payments) domain exists.[^1]'), domains: [{ ...declaration, evidence: ['code.service:nothing'] }] });
    expect(JSON.stringify(bad.answer)).toContain('does not resolve in the graph');
    const badSlug = await session(productSpec).tools.call('write_page', { markdown: page('The [payments](madarch:domain:payments) domain exists.[^1]'), domains: [{ ...declaration, slug: 'Pay Ments' }] });
    expect(JSON.stringify(badSlug.answer)).toContain('lower-case words');
    const unlinked = session(productSpec).tools;
    const notLinked = await unlinked.call('write_page', { markdown: page('The shop takes payments.[^1]'), domains: [declaration] });
    expect((notLinked.answer as { refused: { rule: string }[] }).refused.map((r) => r.rule)).toEqual(['domain-not-linked']);
    const { tools, sink } = session(productSpec);
    const ok = await tools.call('write_page', { markdown: page('The [payments](madarch:domain:payments) domain exists.[^1]'), domains: [declaration] });
    expect(ok.isError).toBe(false);
    expect([...sink.pages.keys()]).toEqual(['docs/product.md']);
    expect(tools.outcome().domains.map((d) => d.slug)).toEqual(['payments']);
  });
});

describe('a run whose product unit fails', () => {
  test('writes nothing, runs no domain unit and reports the refusals', async () => {
    const sink = memorySink();
    const seen: string[] = [];
    const report = await runWriter({
      owner, store, repository, output: path.join(scratch, 'unused-output'), productName: 'Training shop', sink,
      agent: { run: async (request: UnitRequest) => { seen.push(request.id); await request.tools.call('write_page', { markdown: 'no front matter' }); } },
    });
    expect(report.ok).toBe(false);
    expect(report.units).toBe(1);
    expect(seen).toEqual(['product:training-shop']);
    expect(report.product.status).toBe('failed');
    expect(report.product.refusals.map((r) => r.rule)).toEqual(['domains']);
    expect(sink.pages.size).toBe(0);
  });

  test('an agent that throws leaves the unit failed with the reason, and an agent that does nothing leaves it not written', async () => {
    const threw = await runWriter({ owner, store, repository, output: path.join(scratch, 'unused-output'), productName: 'Training shop', sink: memorySink(), agent: { run: async () => { throw new Error('the agent process died'); } } });
    expect(threw.product.status).toBe('failed');
    expect(threw.product.refusals[0]!.message).toContain('the agent process died');
    const idle = await runWriter({ owner, store, repository, output: path.join(scratch, 'unused-output'), productName: 'Training shop', sink: memorySink(), agent: { run: async () => undefined } });
    expect(idle.product.status).toBe('not-written');
    expect(idle.ok).toBe(false);
  });

  test('pages written by an earlier run that this run did not write are named, never deleted', async () => {
    const output = path.join(scratch, 'earlier-output');
    mkdirSync(path.join(output, 'docs/domains'), { recursive: true });
    writeFileSync(path.join(output, 'docs/domains/shipping.md'), 'an earlier page\n');
    const report = await runWriter({ owner, store, repository, output, productName: 'Training shop', sink: memorySink(), agent: { run: async () => undefined } });
    expect(report.stale).toEqual(['docs/domains/shipping.md']);
    expect(readFileSync(path.join(output, 'docs/domains/shipping.md'), 'utf8')).toBe('an earlier page\n');
  });
});

// ---------------------------------------------------------------------------------------------
// The graph indexes what the writer wrote (madarch-m38l.8)
// ---------------------------------------------------------------------------------------------

describe('the graph index of the written pages', () => {
  const sha = (text: string): string => `${text.length}`;
  const git = (cwd: string, ...args: string[]): string => execFileSync('git', args, { cwd, encoding: 'utf8', env: { ...process.env, GIT_AUTHOR_NAME: 'Fixture', GIT_AUTHOR_EMAIL: 'f@example.test', GIT_COMMITTER_NAME: 'Fixture', GIT_COMMITTER_EMAIL: 'f@example.test' } }).trim();
  const repositories = (name: string) => (name === 'repository' ? gitReader(repository) : undefined);
  const pagesOf = () => [...first.pages].map(([file, markdown]) => readIndexedPage(file, markdown, sha));
  const dump = async (db: DatabaseOwner): Promise<string[]> => {
    const nodes = (await db.run((tx) => tx.query<{ line: string }>(
      `SELECT k.key || ' ' || (v.properties->>'key') AS line FROM node_version v JOIN node_kind k ON k.id = v.kind_id
       WHERE v.producer = 'knowledge.index' AND v.valid_to = 'infinity' AND v.recorded_to = 'infinity'`,
    ))).rows.map((r) => `node ${r.line}`);
    const edges = (await db.run((tx) => tx.query<{ line: string }>(
      `SELECT r.key || ' ' || (s.properties->>'key') || ' -> ' || coalesce(d.properties->>'key', d.properties->>'recordKey') AS line
       FROM edge_version e JOIN relation_type r ON r.id = e.relation_type_id
       JOIN node_version s ON s.node_id = e.src_id AND s.valid_to = 'infinity' AND s.recorded_to = 'infinity'
       JOIN node_version d ON d.node_id = e.dst_id AND d.valid_to = 'infinity' AND d.recorded_to = 'infinity'
       WHERE e.producer = 'knowledge.index' AND e.valid_to = 'infinity' AND e.recorded_to = 'infinity'`,
    ))).rows.map((r) => `edge ${r.line}`);
    return [...nodes, ...edges].sort();
  };

  test('every sentence of every page is a statement node of its page, with its grounds as edges; a function\'s page lists the statements that rely on it', async () => {
    const pages = pagesOf();
    const report = await indexKnowledge(owner, store, { productId: 'training-shop', at: view.at, pages, head: { commit: git(repository, 'rev-parse', 'HEAD'), git: gitReader(repository) }, repositories });
    expect(report.unresolved).toEqual([]);
    // The expected count comes from the page text: after the canonical form every statement sentence ends in exactly one footnote.
    const expected = [...first.pages.values()].map((markdown) => markdown.split('\n').filter((l) => !/^\[\^/.test(l)).join('\n').match(/\[\^[a-z0-9-]+\]/g)!.length);
    expect(report.statements).toBe(expected.reduce((a, b) => a + b, 0));
    expect(report.pages).toBe(3);
    const lines = await dump(owner);
    for (const page of pages) {
      for (const statement of page.statements) {
        const key = `statement:${page.id}#${statement.id}`;
        expect(lines).toContain(`node knowledge:statement ${key}`);
        expect(lines).toContain(`edge knowledge:statement-of ${key} -> page:${page.id}`);
        for (const ground of statement.grounds) {
          const end = ground.startsWith('doc:') ? `section:${ground.slice(4)}` : ground;
          expect(lines).toContain(`edge knowledge:grounded-by ${key} -> ${end}`);
        }
      }
    }
    // A function a page grounds a statement on lists that statement.
    const symbol = pages.flatMap((page) => page.statements.flatMap((statement) => statement.grounds.map((ground) => ({ page, statement, ground })))).find((entry) => entry.ground.startsWith('code.symbol:'));
    expect(symbol).toBeDefined();
    const relying = await statementsRelyingOn(owner, symbol!.ground);
    expect(relying.map((r) => `${r.page}#${r.statement}`)).toContain(`${symbol!.page.id}#${symbol!.statement.id}`);
    expect(relying.find((r) => r.statement === symbol!.statement.id)!.text).toBe(symbol!.statement.text);
  });

  test('changing the text of a document section marks the statements grounded on it as changed, and only those', async () => {
    const clone = path.join(scratch, 'changed-clone');
    execFileSync('git', ['clone', '--quiet', '--local', repository, clone]);
    const requirements = readFileSync(path.join(clone, 'docs/requirements.md'), 'utf8');
    const anchored = pagesOf().flatMap((page) => page.statements.flatMap((statement) => statement.grounds.filter((g) => g.startsWith('doc:docs/requirements.md#')).map((ground) => ({ statement, ground }))));
    expect(anchored.length).toBeGreaterThan(0);
    const target = anchored[0]!.ground;
    const section = documentSections(requirements).find((s) => s.anchor === target.slice(target.indexOf('#') + 1))!;
    writeFileSync(path.join(clone, 'docs/requirements.md'), requirements.replace(section.text, `${section.text}\nA new sentence that changes this section.`));
    git(clone, 'commit', '-q', '-am', 'change a requirement');
    const now = { commit: git(clone, 'rev-parse', 'HEAD'), git: gitReader(clone) };
    const changes = await changedGrounds(owner, now);
    const changedGround = new Set(changes.filter((c) => c.status === 'changed').map((c) => c.ground));
    // Sections nest (a heading's section holds its children), so every ground whose own text changed is a section of that document.
    expect(changedGround.has(target)).toBe(true);
    for (const ground of changedGround) expect(ground.startsWith('doc:docs/requirements.md#')).toBe(true);
    // A ground with no digest to compare is unknown, never changed; everything else outside the document stands.
    for (const change of changes) if (!change.ground.startsWith('doc:docs/requirements.md#')) expect(['unchanged', 'unknown']).toContain(change.status);
    // And the same ground at the commit the pages were written at: nothing changed.
    expect((await changedGrounds(owner, { commit: git(repository, 'rev-parse', 'HEAD'), git: gitReader(repository) })).filter((c) => c.status === 'changed' || c.status === 'removed')).toEqual([]);
  });

  test('deleting the graph and refilling restores the same nodes from the Markdown', async () => {
    const before = await dump(owner);
    expect(before.length).toBeGreaterThan(30);
    const rebuilt = createPGliteDatabaseOwner({ btreeGist: true, path: path.join(scratch, 'store-rebuilt') });
    const rebuiltStore = createGraphStore(rebuilt);
    await rebuilt.ready;
    await rebuiltStore.createSchema();
    try {
      await fillGraph({ owner: rebuilt, store: rebuiltStore, repository, extractors: TREE_EXTRACTORS, owners: OWNERS, history: HISTORY_EXTRACTOR, snapshots: KEY.snapshots });
      const rebuiltView = await GraphView.open(rebuilt, rebuiltStore);
      await indexKnowledge(rebuilt, rebuiltStore, { productId: 'training-shop', at: rebuiltView.at, pages: pagesOf(), head: { commit: git(repository, 'rev-parse', 'HEAD'), git: gitReader(repository) }, repositories });
      expect(await dump(rebuilt)).toEqual(before);
    } finally {
      await rebuilt.close();
    }
  }, 1_800_000);
});
